/// Returns true if and only if there exists an element that appears in both slices `a` and `b`.
/// If either slice is empty, returns false.
fn has_common_element(a: &[i32], b: &[i32]) -> bool {
    // For each element in `a`, check if it's contained in `b`.
    a.iter().any(|&x| b.contains(&x))
}

/// Returns true if and only if `val` occurs in slice `s`.
fn slice_contains(s: &[i32], val: i32) -> bool {
    s.contains(&val)
}

